/// @brief Enumeration for Key Manager Errors.
/// @since_tizen 2.3
abstract class key_manager_error_e {
  /// < Successful
  static const int CKMC_ERROR_NONE = 0;

  /// < Invalid function parameter
  static const int CKMC_ERROR_INVALID_PARAMETER = -22;

  /// < Out of memory
  static const int CKMC_ERROR_OUT_OF_MEMORY = -12;

  /// < Permission denied
  static const int CKMC_ERROR_PERMISSION_DENIED = -13;

  /// < Device needed to run API is not supported
  static const int CKMC_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Socket error between client and Central Key Manager
  static const int CKMC_ERROR_SOCKET = -31522815;

  /// < Invalid request from client
  static const int CKMC_ERROR_BAD_REQUEST = -31522814;

  /// < Invalid response from Central Key Manager
  static const int CKMC_ERROR_BAD_RESPONSE = -31522813;

  /// < Transmitting request failed
  static const int CKMC_ERROR_SEND_FAILED = -31522812;

  /// < Receiving response failed
  static const int CKMC_ERROR_RECV_FAILED = -31522811;

  /// < Optional password which used when saving is incorrect
  static const int CKMC_ERROR_AUTHENTICATION_FAILED = -31522810;

  /// < The output buffer size which is passed as parameter is too small
  static const int CKMC_ERROR_BUFFER_TOO_SMALL = -31522809;

  /// < Central Key Manager has been failed for some reason
  static const int CKMC_ERROR_SERVER_ERROR = -31522808;

  /// < The database was not unlocked - user did not login
  static const int CKMC_ERROR_DB_LOCKED = -31522807;

  /// < An internal error inside the database
  static const int CKMC_ERROR_DB_ERROR = -31522806;

  /// < Provided alias already exists in the database
  static const int CKMC_ERROR_DB_ALIAS_EXISTS = -31522805;

  /// < No data for given alias
  static const int CKMC_ERROR_DB_ALIAS_UNKNOWN = -31522804;

  /// < CA certificate(s) were unknown and chain could not be created
  static const int CKMC_ERROR_VERIFICATION_FAILED = -31522803;

  /// < A provided file or binary has not a valid format
  static const int CKMC_ERROR_INVALID_FORMAT = -31522802;

  /// < A provided file doesn't exist or cannot be accessed in the file system
  static const int CKMC_ERROR_FILE_ACCESS_DENIED = -31522801;

  /// < The data is saved as unexportable so it cannot be leaked
  static const int CKMC_ERROR_NOT_EXPORTABLE = -31522800;

  /// < Save key/certificate/pkcs12 failed because of file system error
  static const int CKMC_ERROR_FILE_SYSTEM = -31522799;

  /// < The error with unknown reason
  static const int CKMC_ERROR_UNKNOWN = -31522561;
}

/// @brief Enumeration for key types of key manager.
/// @since_tizen 2.3
abstract class ckmc_key_type {
  /// < Key type not specified
  static const int CKMC_KEY_NONE = 0;

  /// < RSA public key
  static const int CKMC_KEY_RSA_PUBLIC = 1;

  /// < RSA private key
  static const int CKMC_KEY_RSA_PRIVATE = 2;

  /// < ECDSA public key
  static const int CKMC_KEY_ECDSA_PUBLIC = 3;

  /// < ECDSA private key
  static const int CKMC_KEY_ECDSA_PRIVATE = 4;

  /// < DSA public key
  static const int CKMC_KEY_DSA_PUBLIC = 5;

  /// < DSA private key
  static const int CKMC_KEY_DSA_PRIVATE = 6;

  /// < AES key
  static const int CKMC_KEY_AES = 7;
}

/// @brief Enumeration for data format.
/// @since_tizen 2.3
abstract class ckmc_data_format {
  /// < DER format base64 encoded data
  static const int CKMC_FORM_DER_BASE64 = 0;

  /// < DER encoded data
  static const int CKMC_FORM_DER = 1;

  /// < PEM encoded data. It consists of the DER format base64 encoded
  /// with additional header and footer lines.
  static const int CKMC_FORM_PEM = 2;
}

/// @brief Enumeration for elliptic curve.
/// @since_tizen 2.3
abstract class ckmc_ec_type {
  /// < Elliptic curve domain "secp192r1" listed in "SEC 2" recommended
  /// elliptic curve domain
  static const int CKMC_EC_PRIME192V1 = 0;

  /// < "SEC 2" recommended elliptic curve domain - secp256r1
  static const int CKMC_EC_PRIME256V1 = 1;

  /// < NIST curve P-384(covers "secp384r1", the elliptic curve domain
  /// listed in See SEC 2
  static const int CKMC_EC_SECP384R1 = 2;
}

/// @brief Enumeration for hash algorithm.
/// @since_tizen 2.3
abstract class ckmc_hash_algo {
  /// < No Hash Algorithm
  static const int CKMC_HASH_NONE = 0;

  /// < Hash Algorithm SHA1
  static const int CKMC_HASH_SHA1 = 1;

  /// < Hash Algorithm SHA256
  static const int CKMC_HASH_SHA256 = 2;

  /// < Hash Algorithm SHA384
  static const int CKMC_HASH_SHA384 = 3;

  /// < Hash Algorithm SHA512
  static const int CKMC_HASH_SHA512 = 4;
}

/// @brief Enumeration for RSA padding algorithm.
/// @since_tizen 2.3
abstract class ckmc_rsa_padding_algo {
  /// < No Padding
  static const int CKMC_NONE_PADDING = 0;

  /// < PKCS#1 Padding
  static const int CKMC_PKCS1_PADDING = 1;

  /// < X9.31 padding
  static const int CKMC_X931_PADDING = 2;
}

/// @deprecated Deprecated since @if MOBILE 2.4. @elseif WEARABLE 3.0. @endif [Use ckmc_permission_e() instead]
/// @brief Enumeration for database access rights.
/// @since_tizen 2.3
abstract class ckmc_access_right {
  /// < Access right for read
  static const int CKMC_AR_READ = 0;

  /// < Access right for read and remove
  static const int CKMC_AR_READ_REMOVE = 1;
}

/// @brief Enumeration for permissions to access/modify alias.
/// @since_tizen @if MOBILE 2.4 @elseif WEARABLE 3.0 @endif
abstract class ckmc_permission {
  /// < Clear permissions
  static const int CKMC_PERMISSION_NONE = 0;

  /// < Read allowed
  static const int CKMC_PERMISSION_READ = 1;

  /// < Remove allowed
  static const int CKMC_PERMISSION_REMOVE = 2;
}

/// @brief The structure for binary buffer used in key manager CAPI.
/// @since_tizen 2.3
final class __ckmc_raw_buff extends ffi.Struct {
  /// < Byte array containing binary data
  external ffi.Pointer<ffi.UnsignedChar> data;

  /// < The size of the binary data
  @ffi.Size()
  external int size;
}

/// @brief The structure for a policy for storing key/certificate/binary data.
/// @since_tizen 2.3
final class __ckmc_policy extends ffi.Struct {
  /// < Byte array used to encrypt data inside CKM. If it is not null, the data
  /// (or key, or certificate) is stored encrypted with this password inside
  /// key manager
  external ffi.Pointer<ffi.Char> password;

  /// < If true key may be extracted from storage
  @ffi.Bool()
  external bool extractable;
}

/// @brief The structure for key used in key manager CAPI.
/// @since_tizen 2.3
final class __ckmc_key extends ffi.Struct {
  /// < Byte array of key. raw_key may be encrypted with password
  external ffi.Pointer<ffi.UnsignedChar> raw_key;

  /// < The byte size of raw_key
  @ffi.Size()
  external int key_size;

  /// < The raw_key's type
  @ffi.Int32()
  external int key_type;

  /// < Byte array used to decrypt data raw_key inside key manager.
  external ffi.Pointer<ffi.Char> password;
}

/// @brief The structure for certificate used in key manager CAPI.
/// @since_tizen 2.3
final class __ckmc_cert extends ffi.Struct {
  /// < Byte array of certificate
  external ffi.Pointer<ffi.UnsignedChar> raw_cert;

  /// < Byte size of raw_cert
  @ffi.Size()
  external int cert_size;

  /// < Raw_cert's encoding format
  @ffi.Int32()
  external int data_format;
}

/// @brief The structure for linked list of alias.
/// @since_tizen 2.3
final class __ckmc_alias_list extends ffi.Struct {
  /// < The name of key, certificate or data stored in key manager
  external ffi.Pointer<ffi.Char> alias;

  /// < The pointer pointing to the next ckmc_alias_list_s
  external ffi.Pointer<__ckmc_alias_list> next;
}

final class ckmc_alias_info_s extends ffi.Opaque {}

/// @brief The structure for linked list of alias with additional information.
/// @since_tizen 5.5
final class __ckmc_alias_info_list_s extends ffi.Struct {
  /// < The pointer pointing to the alias structure
  /// with additional information
  external ffi.Pointer<ckmc_alias_info_s> info;

  /// < The pointer pointing to the next ckmc_alias_info_list_s
  external ffi.Pointer<__ckmc_alias_info_list_s> next;
}

/// @brief The structure for linked list of ckmc_cert_s
/// @since_tizen 2.3
final class __ckmc_cert_list extends ffi.Struct {
  /// < The pointer of ckmc_cert_s
  external ffi.Pointer<ckmc_cert_s> cert;

  /// < The pointer pointing to the next ckmc_cert_list_s
  external ffi.Pointer<__ckmc_cert_list> next;
}

/// @brief The structure for certificate used in key manager CAPI.
/// @since_tizen 2.3
typedef ckmc_cert_s = __ckmc_cert;

/// @brief Enumeration for OCSP status.
/// @since_tizen @if MOBILE 2.4 @elseif WEARABLE 3.0 @endif
abstract class ckmc_ocsp_status {
  /// < OCSP status is good
  static const int CKMC_OCSP_STATUS_GOOD = 0;

  /// < The certificate is revoked
  static const int CKMC_OCSP_STATUS_REVOKED = 1;

  /// < Unknown error
  static const int CKMC_OCSP_STATUS_UNKNOWN = 2;

  /// < The certificate does not provide OCSP extension
  static const int CKMC_OCSP_ERROR_UNSUPPORTED = 3;

  /// < The invalid URL in certificate OCSP extension
  static const int CKMC_OCSP_ERROR_INVALID_URL = 4;

  /// < The invalid response from OCSP server
  static const int CKMC_OCSP_ERROR_INVALID_RESPONSE = 5;

  /// < OCSP remote server error
  static const int CKMC_OCSP_ERROR_REMOTE = 6;

  /// < Network connection error
  static const int CKMC_OCSP_ERROR_NET = 7;

  /// < OpenSSL API error
  static const int CKMC_OCSP_ERROR_INTERNAL = 8;
}

/// @brief The structure for PKCS12 used in key manager CAPI.
/// @since_tizen @if MOBILE 2.4 @elseif WEARABLE 3.0 @endif
