  external ffi.Pointer<ckmc_key_s> priv_key;

  /// < The certificate, may be null
  external ffi.Pointer<ckmc_cert_s> cert;

  /// < The chain certificate list, may be null
  external ffi.Pointer<ckmc_cert_list_s> ca_chain;
}

