/// @brief Enumeration for crypto algorithm parameters.
/// @since_tizen 3.0
/// @see #ckmc_algo_type_e
abstract class ckmc_param_name {
  static const int CKMC_PARAM_ALGO_TYPE = 1;

  /// < 16B buffer (up to 2^64-1 bytes long in case of AES GCM)
  static const int CKMC_PARAM_ED_IV = 101;

  /// < integer - ctr length in bits
  static const int CKMC_PARAM_ED_CTR_LEN = 102;

  /// < buffer
  static const int CKMC_PARAM_ED_AAD = 103;

  /// < integer - tag length in bits
  static const int CKMC_PARAM_ED_TAG_LEN = 104;

  /// < buffer
  static const int CKMC_PARAM_ED_LABEL = 105;
}

final class __ckmc_param_list extends ffi.Opaque {}

/// @brief Enumeration for crypto algorithm types.
/// @since_tizen 3.0
/// @see #ckmc_param_name_e
abstract class ckmc_algo_type {
  /// < AES-CTR algorithm
  /// Supported parameters:
  /// - CKMC_PARAM_ALGO_TYPE = CKMC_ALGO_AES_CTR(mandatory),
  /// - CKMC_PARAM_ED_IV = 16-byte initialization vector(mandatory)
  /// - CKMC_PARAM_ED_CTR_LEN = length of counter block in bits
  /// (optional, only 128b is supported at the moment)
  static const int CKMC_ALGO_AES_CTR = 1;

  /// < AES-CBC algorithm
  /// Supported parameters:
  /// - CKMC_PARAM_ALGO_TYPE = CKMC_ALGO_AES_CBC(mandatory),
  /// - CKMC_PARAM_ED_IV = 16-byte initialization vector(mandatory)
  static const int CKMC_ALGO_AES_CBC = 2;

  /// < AES-GCM algorithm
  /// Supported parameters:
  /// - CKMC_PARAM_ALGO_TYPE = CKMC_ALGO_AES_GCM(mandatory),
  /// - CKMC_PARAM_ED_IV = initialization vector(mandatory)
  /// - CKMC_PARAM_ED_TAG_LEN = GCM tag length in bits. One of
  /// {32, 64, 96, 104, 112, 120, 128} (optional, if not present, the
  /// length 128 is used; since Tizen 5.0, if TrustZone backend is used,
  /// 32 and 64 lengths are not supported)
  /// - CKMC_PARAM_ED_AAD = additional authentication data(optional)
  static const int CKMC_ALGO_AES_GCM = 3;

  /// < AES-CFB algorithm
  /// Supported parameters:
  /// - CKMC_PARAM_ALGO_TYPE = CKMC_ALGO_AES_CFB(mandatory),
  /// - CKMC_PARAM_ED_IV = 16-byte initialization vector(mandatory)
  static const int CKMC_ALGO_AES_CFB = 4;

  /// < RSA-OAEP algorithm
  /// Supported parameters:
  /// - CKMC_PARAM_ALGO_TYPE = CKMC_ALGO_RSA_OAEP(required),
  /// - CKMC_PARAM_ED_LABEL = label to be associated with the message
  /// (optional, not supported at the moment)
  static const int CKMC_ALGO_RSA_OAEP = 5;
}

